// ===================== stepper_ctrl.cpp =====================

namespace stepper {
namespace {

bool running = false;
bool continuous = false;
int dirSign = 1;           // +1 = DIR HIGH
long stepsRemaining = 0;
long position = 0;         // absolute position in (micro)steps since boot
float rpmNow = DEFAULT_RPM;
uint32_t intervalUs = 0;
uint32_t lastStepUs = 0;

// Speeds in STEP pulses per second, acceleration in pulses/s^2.
float vTarget = 0;  // cruise speed
float vStart = 0;   // start/stop speed
float v = 0;        // current speed
const float ACCEL_SPS2 = ACCEL_RPM_PER_S * STEPS_PER_REV / 60.0f;

float rpmToSps(float rpm) { return rpm * STEPS_PER_REV / 60.0f; }  // pulses/s = RPM x steps/rev / 60

void setSpeed(float rpm) {
  rpmNow = constrain(fabsf(rpm), 0.1f, MAX_RPM);
  vTarget = rpmToSps(rpmNow);
}

void startProfile() {  // begin a move from standstill
  vStart = min(rpmToSps(START_RPM), vTarget);
  v = vStart;
  intervalUs = (uint32_t)(1000000.0f / v);
}

// After each step: v^2 = v0^2 +/- 2*a*(1 step). Decelerate when the remaining steps are
// just enough to slow down to vStart, otherwise accelerate (or slow) towards vTarget.
void updateSpeed() {
  const float stopSteps = (v * v - vStart * vStart) / (2.0f * ACCEL_SPS2);
  if (!continuous && stepsRemaining <= stopSteps) {
    v = sqrtf(max(v * v - 2.0f * ACCEL_SPS2, vStart * vStart));
  } else if (v < vTarget) {
    v = min(vTarget, sqrtf(v * v + 2.0f * ACCEL_SPS2));
  } else if (v > vTarget) {
    v = max(vTarget, sqrtf(max(v * v - 2.0f * ACCEL_SPS2, 0.0f)));
  }
  intervalUs = (uint32_t)(1000000.0f / v);
}

void setDirection(int sign) {
  dirSign = sign >= 0 ? 1 : -1;
  digitalWrite(pins::DIR, dirSign > 0 ? HIGH : LOW);
}

}  // namespace

void begin() {
  pinMode(pins::STEP, OUTPUT);
  pinMode(pins::DIR, OUTPUT);
  digitalWrite(pins::STEP, LOW);
  digitalWrite(pins::DIR, LOW);
  setSpeed(DEFAULT_RPM);
}

void update() {
  if (!running) return;
  const uint32_t now = micros();
  if ((uint32_t)(now - lastStepUs) < intervalUs) return;
  lastStepUs = now;

  digitalWrite(pins::STEP, HIGH);
  delayMicroseconds(3);
  digitalWrite(pins::STEP, LOW);
  position += dirSign;

  if (!continuous && --stepsRemaining <= 0) {
    running = false;
    return;
  }
  updateSpeed();
}

void moveSteps(long steps, float rpm) {
  if (steps == 0) return;
  setDirection(steps > 0 ? 1 : -1);
  delayMicroseconds(5);  // DIR setup time before the first STEP edge
  setSpeed(rpm);
  startProfile();
  stepsRemaining = labs(steps);
  continuous = false;
  running = true;
  lastStepUs = micros();
}

float moveDegrees(float deg, float rpm) {
  const long steps = lroundf(deg / DEG_PER_STEP);
  moveSteps(steps, rpm);
  return steps * DEG_PER_STEP;
}

float moveToDegrees(float deg, float rpm) {
  const long target = lroundf(deg / DEG_PER_STEP);
  const long steps = target - position;
  if (steps == 0) {
    if (!continuous) stop();
  } else if (running && !continuous && (steps > 0) == (dirSign > 0)) {
    stepsRemaining = labs(steps);  // same direction: just change how far to go, keep the step timing
    setSpeed(rpm);
  } else {
    moveSteps(steps, rpm);
  }
  return target * DEG_PER_STEP;
}

void runContinuous(bool forward, float rpm) {
  setDirection(forward ? 1 : -1);
  delayMicroseconds(5);
  setSpeed(rpm);
  startProfile();
  continuous = true;
  running = true;
  lastStepUs = micros();
}

void stop() {
  running = false;
  continuous = false;
  stepsRemaining = 0;
}

bool isMoving() { return running; }
bool isContinuous() { return continuous; }
long positionSteps() { return position; }
float positionDeg() { return position * DEG_PER_STEP; }
float currentRpm() { return rpmNow; }

}  // namespace stepper

// ===================== tof_swipe.cpp =====================

#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>
#include <freertos/task.h>

#ifndef SIM_TOF
#include <Wire.h>
#include <SparkFun_VL53L5CX_Library.h>
#endif

namespace tof {
namespace {

// ---------------- Tunables (from Mayank's tested bringup/tof_swipe) ----------------
constexpr uint32_t I2C_HZ = 400000;
constexpr int W = COLUMNS;         // 4x4 zones: enough for left/right, allows a high frame rate
constexpr int RANGING_HZ = 30;
constexpr int HAND_MIN_MM = 30;
constexpr int HAND_MAX_MM = 400;   // hand must be closer than this
constexpr int BG_MARGIN_MM = 100;  // and this much closer than the background
constexpr int MIN_HAND_ZONES = 1;
constexpr float SWIPE_MIN_DX = 1.5f;  // columns travelled (range is 0..W-1)
constexpr uint32_t SWIPE_MIN_MS = 60;
constexpr uint32_t SWIPE_MAX_MS = 1500;
constexpr int GONE_FRAMES = 3;
constexpr uint32_t COOLDOWN_MS = 600;
constexpr int CALIB_FRAMES = 30;
constexpr bool MIRROR_X = false;   // tested on hardware: false gives correct LEFT/RIGHT

int16_t distMm[W * W];
uint8_t zoneStatus[W * W];
float bgMm[W * W];

QueueHandle_t swipeQueue;
portMUX_TYPE statusMux = portMUX_INITIALIZER_UNLOCKED;
Status shared = {State::INIT, false, -1.0f, 0, 0};

void setState(State s) {
  portENTER_CRITICAL(&statusMux);
  shared.state = s;
  portEXIT_CRITICAL(&statusMux);
}

bool zoneValid(uint8_t s) { return s == 5 || s == 9; }

// ---------------- Frame source: real sensor or simulated slide pot ----------------
#ifndef SIM_TOF
SparkFun_VL53L5CX imager;
VL53L5CX_ResultsData data;

bool sensorBegin() {
  Wire.begin(pins::TOF_SDA, pins::TOF_SCL);
  Wire.setClock(I2C_HZ);
  if (!imager.begin()) return false;  // uploads ~90 KB of sensor firmware: takes a few seconds
  imager.setResolution(W * W);
  imager.setRangingFrequency(RANGING_HZ);
  imager.startRanging();
  return true;
}

bool readFrame() {
  if (!imager.isDataReady()) return false;
  if (!imager.getRangingData(&data)) return false;
  for (int i = 0; i < W * W; i++) {
    distMm[i] = data.distance_mm[i];
    zoneStatus[i] = data.target_status[i];
  }
  return true;
}
#else
// Slider at either end (outer 3%) = no hand. In between, the slider position is the hand's x.
// A hand between two columns is drawn in both, at distances chosen so the 1/distance-weighted
// mean column comes out at the exact slider position, so the real tracking code sees smooth motion.
bool sensorBegin() {
  pinMode(pins::SIM_TOF_SLIDER, INPUT);
  return true;
}

bool readFrame() {
  static uint32_t lastMs = 0;
  const uint32_t now = millis();
  if (now - lastMs < 1000 / RANGING_HZ) return false;
  lastMs = now;
  const float u = analogRead(pins::SIM_TOF_SLIDER) / 4095.0f;
  for (int i = 0; i < W * W; i++) {
    distMm[i] = 1200;  // background wall
    zoneStatus[i] = 5;
  }
  constexpr float EDGE = 0.03f;
  if (u > EDGE && u < 1.0f - EDGE) {
    const float x = (u - EDGE) / (1.0f - 2 * EDGE) * (W - 1);  // 0..W-1
    const int c0 = min((int)floorf(x), W - 1);
    const float f = x - c0;
    for (int row = 0; row < W; row++) {
      if (c0 == W - 1 || f < 0.1f) {
        distMm[row * W + c0] = 150;
      } else if (f > 0.9f) {
        distMm[row * W + c0 + 1] = 150;
      } else {  // weights 1/d0 and 1/d1 give mean column c0 + d0 / (d0 + d1) = c0 + f
        distMm[row * W + c0] = (int16_t)(300 * f);
        distMm[row * W + c0 + 1] = (int16_t)(300 * (1 - f));
      }
    }
  }
  return true;
}
#endif

void calibrateBackground() {
  float sum[W * W] = {0};
  int count[W * W] = {0};
  int frames = 0;
  while (frames < CALIB_FRAMES) {
    if (!readFrame()) { vTaskDelay(1); continue; }
    for (int i = 0; i < W * W; i++) {
      if (zoneValid(zoneStatus[i])) { sum[i] += distMm[i]; count[i]++; }
    }
    frames++;
  }
  for (int i = 0; i < W * W; i++) bgMm[i] = count[i] ? sum[i] / count[i] : 4000.0f;
}

void task(void *) {
  if (!sensorBegin()) {
    setState(State::ERROR);
    vTaskDelete(nullptr);
  }
  setState(State::CALIBRATING);
  calibrateBackground();
  setState(State::READY);

  bool tracking = false;
  float startX = 0, lastX = 0;
  uint32_t startMs = 0, lastSeenMs = 0, lastSwipeMs = 0;
  int goneCount = 0;

  for (;;) {
    if (!readFrame()) { vTaskDelay(1); continue; }
    const uint32_t now = millis();

    // --- Hand zones and their 1/distance-weighted x-position ---
    float wSum = 0, xSum = 0;
    int handZones = 0, nearestMm = 0;
    for (int row = 0; row < W; row++) {
      for (int col = 0; col < W; col++) {
        const int i = row * W + col;
        if (!zoneValid(zoneStatus[i])) continue;
        const int d = distMm[i];
        if (d < HAND_MIN_MM || d > HAND_MAX_MM) continue;
        if (d > bgMm[i] - BG_MARGIN_MM) continue;
        const int x = MIRROR_X ? (W - 1 - col) : col;
        const float w = 1.0f / d;
        xSum += w * x;
        wSum += w;
        handZones++;
        if (nearestMm == 0 || d < nearestMm) nearestMm = d;
      }
    }
    const bool present = handZones >= MIN_HAND_ZONES;
    const float x = present ? xSum / wSum : -1.0f;

    // --- Swipe state machine ---
    if (present) {
      if (!tracking && now - lastSwipeMs > COOLDOWN_MS) {
        tracking = true;
        startX = x;
        startMs = now;
      }
      if (tracking) {
        lastX = x;
        lastSeenMs = now;
        goneCount = 0;
      }
    } else if (tracking && ++goneCount >= GONE_FRAMES) {
      tracking = false;
      const uint32_t dur = lastSeenMs - startMs;
      const float dx = lastX - startX;
      if (dur >= SWIPE_MIN_MS && dur <= SWIPE_MAX_MS && fabsf(dx) >= SWIPE_MIN_DX) {
        const int8_t dir = dx > 0 ? 1 : -1;
        xQueueSend(swipeQueue, &dir, 0);
        lastSwipeMs = now;
      }
    }

    portENTER_CRITICAL(&statusMux);
    shared.handPresent = present;
    shared.handX = x;
    shared.nearestMm = nearestMm;
    shared.frames++;
    portEXIT_CRITICAL(&statusMux);
  }
}

}  // namespace

void begin() {
  swipeQueue = xQueueCreate(4, sizeof(int8_t));
  xTaskCreatePinnedToCore(task, "tof", 8192, nullptr, 1, nullptr, 0);
}

Status status() {
  portENTER_CRITICAL(&statusMux);
  const Status s = shared;
  portEXIT_CRITICAL(&statusMux);
  return s;
}

int pollSwipe() {
  int8_t dir = 0;
  if (swipeQueue && xQueueReceive(swipeQueue, &dir, 0) == pdTRUE) return dir;
  return 0;
}

void injectSwipe(int dir) {
  const int8_t d = dir > 0 ? 1 : -1;
  if (swipeQueue) xQueueSend(swipeQueue, &d, 0);
}

const char *stateName(State s) {
  switch (s) {
    case State::INIT: return "INIT";
    case State::CALIBRATING: return "CALIBRATING";
    case State::READY: return "READY";
    default: return "ERROR";
  }
}

}  // namespace tof

// ===================== flex_servo.cpp =====================

#include <ESP32Servo.h>

// Calibration in millivolts at the ADC pin. BillyChern measured 477 (straight) and 521 (bent)
// ADC counts on the Uno with a 5 V divider. With the divider on the ESP32's 3V3, the same
// ratio gives about 1539 mV and 1681 mV. RE-MEASURE on the ESP32 (watch flex_raw_mv).
#ifndef FLEX_STRAIGHT_MV
#define FLEX_STRAIGHT_MV 1539
#endif
#ifndef FLEX_BENT_MV
#define FLEX_BENT_MV 1681
#endif

namespace flexservo {
namespace {

constexpr int SENSOR_MIN_DEG = 70;   // sensor-mode command range from BillyChern's bench test
constexpr int SENSOR_MAX_DEG = 150;
constexpr float SMOOTHING = 0.15f;   // EMA factor at a 20 ms sample period
constexpr uint32_t SAMPLE_MS = 20;

Servo servo;
int raw = 0;
float filtered = 0;
float fraction = 0;
int command = SENSOR_MIN_DEG;
uint32_t lastSampleMs = 0;

}  // namespace

void begin() {
  analogSetPinAttenuation(pins::FLEX, ADC_11db);  // full 0-3.3 V range
  raw = analogReadMilliVolts(pins::FLEX);
  filtered = raw;
  servo.setPeriodHertz(50);
  servo.attach(pins::SERVO);
  servo.write(command);
}

void update(bool sensorMode) {
  const uint32_t now = millis();
  if (now - lastSampleMs < SAMPLE_MS) return;
  lastSampleMs = now;

  raw = analogReadMilliVolts(pins::FLEX);
  filtered += SMOOTHING * (raw - filtered);

  // Works whether bending raises or lowers the voltage.
  fraction = 0.0f;
  if (FLEX_STRAIGHT_MV != FLEX_BENT_MV) {
    fraction = (filtered - FLEX_STRAIGHT_MV) / float(FLEX_BENT_MV - FLEX_STRAIGHT_MV);
  }
  fraction = constrain(fraction, 0.0f, 1.0f);

  if (sensorMode) {
    command = SENSOR_MIN_DEG + int(fraction * (SENSOR_MAX_DEG - SENSOR_MIN_DEG) + 0.5f);
    servo.write(command);
  }
}

int setServoDeg(int deg) {
  command = constrain(deg, GUI_MIN_DEG, GUI_MAX_DEG);
  servo.write(command);
  return command;
}

int rawMv() { return raw; }
float filteredMv() { return filtered; }
float bendPct() { return fraction * 100.0f; }
int servoDeg() { return command; }

}  // namespace flexservo

// ===================== ir_dc.cpp =====================

namespace irdc {
namespace {

// Mayanka's Uno thresholds were 100 (far) and 600 (near) ADC counts at a 5 V reference,
// i.e. about 490 mV and 2930 mV. Using millivolts keeps them valid on the ESP32's 12-bit ADC.
// The Sharp output stays below ~3.1 V even with the sensor on 5 V, so it is safe for the ESP32 pin.
constexpr int FAR_MV = 490;    // hand far  -> motor off
constexpr int NEAR_MV = 2930;  // hand near -> full speed
constexpr int MIN_SPEED = 0;
constexpr int MAX_SPEED = 255;
constexpr uint32_t SAMPLE_MS = 50;
constexpr uint32_t PWM_HZ = 1000;
constexpr uint8_t PWM_BITS = 8;

int ir = 0;
int pwmSigned = 0;
uint32_t lastSampleMs = 0;

void apply(int signedPwm) {
  pwmSigned = constrain(signedPwm, -MAX_SPEED, MAX_SPEED);
  digitalWrite(pins::DC_IN1, pwmSigned >= 0 ? HIGH : LOW);
  digitalWrite(pins::DC_IN2, pwmSigned >= 0 ? LOW : HIGH);
#if ESP_ARDUINO_VERSION_MAJOR >= 3
  ledcWrite(pins::DC_ENA, abs(pwmSigned));
#else
  ledcWrite(15, abs(pwmSigned));  // core 2.x: high channel, away from ESP32Servo
#endif
}

}  // namespace

void begin() {
  pinMode(pins::DC_IN1, OUTPUT);
  pinMode(pins::DC_IN2, OUTPUT);
#if ESP_ARDUINO_VERSION_MAJOR >= 3
  ledcAttach(pins::DC_ENA, PWM_HZ, PWM_BITS);
#else
  ledcSetup(15, PWM_HZ, PWM_BITS);
  ledcAttachPin(pins::DC_ENA, 15);
#endif
  analogSetPinAttenuation(pins::IR, ADC_11db);
  apply(0);
}

void update(bool sensorMode) {
  const uint32_t now = millis();
  if (now - lastSampleMs < SAMPLE_MS) return;
  lastSampleMs = now;

  ir = analogReadMilliVolts(pins::IR);
  if (sensorMode) {
    // Higher voltage = closer hand = faster, forward only (same as the Uno sketch).
    const int mv = constrain(ir, FAR_MV, NEAR_MV);
    apply(map(mv, FAR_MV, NEAR_MV, MIN_SPEED, MAX_SPEED));
  }
}

int setPwm(int signedPwm) {
  apply(signedPwm);
  return pwmSigned;
}

void stop() { apply(0); }

int irMv() { return ir; }
int pwm() { return pwmSigned; }

}  // namespace irdc

// ===================== main.cpp =====================
// TSP05 Sensors & Motor Control Lab: integrated firmware for one ESP32.
//
//   Sharp IR      -> DC motor speed  (ir_dc.cpp,       from Mayanka's IR_distance.ino)
//   Flex sensor   -> RC servo angle  (flex_servo.cpp,  from BillyChern's flex_servo.ino)
//   VL53L5CX      -> stepper, two styles (`tof swipe` / `tof follow`):
//                    swipe:  each left/right swipe turns it +/-45 deg (tof_swipe.cpp, from Mayank's tof_swipe)
//                    follow: the stepper angle tracks the hand's left-right position
//                    (stepper_ctrl.cpp, from Rai's stepper controller)
//   Pushbutton    -> toggles GUI / SENSOR mode (debounced in software)
//
// Serial (115200): type `help`. Telemetry is printed every 100 ms as `name:value` pairs,
// which the Arduino IDE Serial Plotter can graph. Event lines start with `#`.

namespace {

constexpr float SWIPE_DEG = 45.0f;  // stepper move per swipe (CONTEXT.md open question 11)
// Follow mode: hand at the far left of the ToF view -> -FOLLOW_SPAN_DEG/2, far right -> +FOLLOW_SPAN_DEG/2.
constexpr float FOLLOW_SPAN_DEG = 180.0f;
constexpr float FOLLOW_ALPHA = 0.3f;         // EMA on hand x per frame: smooths ToF jitter
constexpr float FOLLOW_DEADBAND_DEG = 2.0f;  // ignore target changes smaller than this
constexpr uint32_t DEBOUNCE_MS = 30;
constexpr uint32_t TELEMETRY_MS = 100;

Mode mode = Mode::GUI;  // start in GUI mode so nothing moves on its own at power-up
enum class TofControl { SWIPE, FOLLOW };
TofControl tofControl = TofControl::SWIPE;
// Stepper speed when the ToF drives it (swipe and follow). Change at runtime with `speed <rpm>`.
// Moves ramp up from stepper::START_RPM. If the motor buzzes or skips instead of turning, lower it.
float sensorRpm = 180.0f;
bool telemetryOn = true;
String line;

const char *modeName() { return mode == Mode::GUI ? "GUI" : "SENSOR"; }

void setMode(Mode m) {
  mode = m;
  // Leaving either mode: stop the motors that run continuously so nothing keeps going unattended.
  stepper::stop();
  irdc::stop();
  while (tof::pollSwipe() != 0) {}  // drop swipes that happened before the switch
  Serial.printf("# MODE %s\n", modeName());
}

// ---------------- Debounced pushbutton ----------------
void updateButton() {
  static int stable = HIGH, lastRead = HIGH;
  static uint32_t changedMs = 0;
  const int r = digitalRead(pins::BUTTON);
  if (r != lastRead) {
    lastRead = r;
    changedMs = millis();
  }
  if (r != stable && millis() - changedMs >= DEBOUNCE_MS) {
    stable = r;
    if (stable == LOW) setMode(mode == Mode::GUI ? Mode::SENSOR : Mode::GUI);  // on press
  }
}

// ---------------- Serial commands ----------------
void printHelp() {
  Serial.println(F("# Commands (any mode):"));
  Serial.println(F("#   mode [gui|sensor]   no argument = toggle (same as the button)"));
  Serial.println(F("#   stop                stop stepper and DC motor"));
  Serial.println(F("#   status | help | tele on|off"));
  Serial.println(F("#   tof swipe|follow    ToF -> stepper style: +/-45 deg per swipe, or follow the hand"));
  Serial.println(F("#   speed <rpm>         stepper speed in SENSOR mode (GUI: step <deg> <rpm>)"));
  Serial.println(F("#   swipe left|right    fake a ToF swipe (acts in SENSOR mode, swipe style)"));
  Serial.println(F("# Commands (GUI mode only):"));
  Serial.println(F("#   step <deg> [rpm]    relative stepper move, e.g. step 37 or step -90 20"));
  Serial.println(F("#   move <steps> <rpm>  forward <rpm>  reverse <rpm>"));
  Serial.println(F("#   servo <deg>         0-180"));
  Serial.println(F("#   dc <pwm>            -255..255, sign = direction"));
}

void printStatus() {
  const tof::Status t = tof::status();
  Serial.printf("# mode=%s tof_control=%s | stepper pos=%.3f deg (%ld steps) %s rpm=%.1f | servo=%d deg | dc_pwm=%d | "
                "ir=%d mV | flex=%d mV (%.1f%%) | tof=%s frames=%lu\n",
                modeName(), tofControl == TofControl::FOLLOW ? "follow" : "swipe", stepper::positionDeg(), stepper::positionSteps(),
                stepper::isMoving() ? "MOVING" : "IDLE", stepper::currentRpm(), flexservo::servoDeg(),
                irdc::pwm(), irdc::irMv(), flexservo::rawMv(), flexservo::bendPct(), tof::stateName(t.state),
                (unsigned long)t.frames);
}

bool guiOnly() {
  if (mode == Mode::GUI) return true;
  Serial.println(F("# ignored: switch to GUI mode first (`mode gui` or press the button)"));
  return false;
}

void handleCommand(String cmd) {
  cmd.trim();
  cmd.toLowerCase();
  if (cmd.length() == 0) return;
  const char *c = cmd.c_str();
  float a, b;
  long n;
  char word[16];

  if (cmd == "help") printHelp();
  else if (cmd == "status") printStatus();
  else if (cmd == "stop") { stepper::stop(); irdc::stop(); Serial.println(F("# stopped")); }
  else if (cmd == "mode") setMode(mode == Mode::GUI ? Mode::SENSOR : Mode::GUI);
  else if (cmd == "mode gui") setMode(Mode::GUI);
  else if (cmd == "mode sensor") setMode(Mode::SENSOR);
  else if (cmd == "tele on") telemetryOn = true;
  else if (cmd == "tele off") telemetryOn = false;
  else if (cmd == "tof swipe") { tofControl = TofControl::SWIPE; stepper::stop(); Serial.println(F("# TOF CONTROL swipe")); }
  else if (sscanf(c, "speed %f", &a) == 1) {
    sensorRpm = constrain(a, 1.0f, stepper::MAX_RPM);
    Serial.printf("# SPEED %.1f rpm (sensor-driven stepper)\n", sensorRpm);
  }
  else if (cmd == "tof follow") { tofControl = TofControl::FOLLOW; stepper::stop(); Serial.println(F("# TOF CONTROL follow")); }
  else if (sscanf(c, "swipe %15s", word) == 1) tof::injectSwipe(strcmp(word, "right") == 0 ? 1 : -1);
  else if (sscanf(c, "step %f %f", &a, &b) == 2) {
    if (guiOnly()) Serial.printf("# STEP requested %.3f deg -> actual %.3f deg\n", a, stepper::moveDegrees(a, b));
  } else if (sscanf(c, "step %f", &a) == 1) {
    if (guiOnly()) Serial.printf("# STEP requested %.3f deg -> actual %.3f deg\n", a, stepper::moveDegrees(a));
  } else if (sscanf(c, "move %ld %f", &n, &b) == 2) {
    if (guiOnly()) { stepper::moveSteps(n, b); Serial.printf("# MOVE %ld steps\n", n); }
  } else if (sscanf(c, "forward %f", &b) == 1) {
    if (guiOnly()) stepper::runContinuous(true, b);
  } else if (sscanf(c, "reverse %f", &b) == 1) {
    if (guiOnly()) stepper::runContinuous(false, b);
  } else if (sscanf(c, "servo %f", &a) == 1) {
    if (guiOnly()) Serial.printf("# SERVO %d deg\n", flexservo::setServoDeg(lroundf(a)));
  } else if (sscanf(c, "dc %f", &a) == 1) {
    if (guiOnly()) Serial.printf("# DC pwm %d\n", irdc::setPwm(lroundf(a)));
  } else Serial.printf("# unknown command: %s (type help)\n", c);
}

void readSerial() {
  while (Serial.available()) {
    const char ch = Serial.read();
    if (ch == '\n' || ch == '\r') {
      if (line.length()) handleCommand(line);
      line = "";
    } else if (line.length() < 100) {
      line += ch;
    }
  }
}

// ---------------- Sensor -> stepper ----------------
// Follow style: once per new ToF frame, point the stepper at the (smoothed) hand x.
// When the hand leaves, the stepper holds its last position.
void handleFollow() {
  static uint32_t lastFrame = 0;
  static bool tracking = false;
  static float xSmooth = 0, lastTarget = 0;
  while (tof::pollSwipe() != 0) {}  // swipes are not used in this style

  const tof::Status t = tof::status();
  if (t.frames == lastFrame) return;
  lastFrame = t.frames;
  if (mode != Mode::SENSOR || !t.handPresent) {
    tracking = false;
    return;
  }
  if (!tracking) {  // hand just appeared: start the filter at its position
    tracking = true;
    xSmooth = t.handX;
    lastTarget = stepper::positionDeg();
  }
  xSmooth += FOLLOW_ALPHA * (t.handX - xSmooth);
  const float target = (xSmooth / (tof::COLUMNS - 1) - 0.5f) * FOLLOW_SPAN_DEG;
  if (fabsf(target - lastTarget) < FOLLOW_DEADBAND_DEG) return;
  lastTarget = stepper::moveToDegrees(target, sensorRpm);
}

void handleSwipes() {
  if (tofControl == TofControl::FOLLOW) {
    handleFollow();
    return;
  }
  const int dir = tof::pollSwipe();
  if (dir == 0) return;
  if (mode != Mode::SENSOR) {
    Serial.printf("# SWIPE %s (GUI mode: stepper not moved)\n", dir > 0 ? "RIGHT" : "LEFT");
    return;
  }
  if (stepper::isMoving()) {
    Serial.println(F("# SWIPE ignored: stepper still moving"));
    return;
  }
  const float actual = stepper::moveDegrees(dir * SWIPE_DEG, sensorRpm);
  Serial.printf("# SWIPE %s -> stepper %+.3f deg\n", dir > 0 ? "RIGHT" : "LEFT", actual);
}

void printTelemetry() {
  static uint32_t lastMs = 0;
  static tof::State lastTofState = tof::State::INIT;
  const uint32_t now = millis();
  if (now - lastMs < TELEMETRY_MS) return;
  lastMs = now;

  const tof::Status t = tof::status();
  if (t.state != lastTofState) {
    lastTofState = t.state;
    Serial.printf("# TOF %s%s\n", tof::stateName(t.state),
                  t.state == tof::State::CALIBRATING ? " (keep your hand away from the sensor)" : "");
  }
  if (!telemetryOn) return;
  // Telemetry contract (parsed by ros2_ws/src/tsp05_bridge/tsp05_bridge/protocol.py):
  // one line of space-separated `key:number` pairs. Add keys freely; don't rename existing ones.
  Serial.printf("sensor_mode:%d tof_follow:%d tof_state:%d ir_mv:%d dc_pwm:%d flex_raw_mv:%d flex_filt_mv:%.0f "
                "bend_pct:%.1f servo_deg:%d hand:%d hand_x:%.2f hand_mm:%d step_deg:%.3f step_moving:%d\n",
                mode == Mode::SENSOR, tofControl == TofControl::FOLLOW, (int)t.state, irdc::irMv(), irdc::pwm(),
                flexservo::rawMv(), flexservo::filteredMv(), flexservo::bendPct(), flexservo::servoDeg(),
                t.handPresent, t.handX, t.nearestMm, stepper::positionDeg(), stepper::isMoving());
}

}  // namespace

void setup() {
  Serial.setTxBufferSize(1024);  // printing must not block, or the stepper pulses stutter
  Serial.begin(115200);
  delay(300);
  Serial.println(F("\n# TSP05 integrated firmware"));
#ifdef SIM_TOF
  Serial.println(F("# SIMULATION build: ToF replaced by the slide pot (drag it end to end = swipe)"));
#endif

  pinMode(pins::BUTTON, INPUT_PULLUP);
  stepper::begin();
  flexservo::begin();  // attach the servo before the DC PWM so they get separate LEDC channels
  irdc::begin();
  tof::begin();        // background task on core 0; sensor firmware upload takes a few seconds

  printHelp();
  Serial.printf("# MODE %s\n", modeName());
}

void loop() {
  stepper::update();
  updateButton();
  readSerial();
  const bool sensorMode = mode == Mode::SENSOR;
  irdc::update(sensorMode);
  flexservo::update(sensorMode);
  handleSwipes();
  printTelemetry();
}
